#include "stdlib/stats/base/dists/halfnormal/logcdf.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/erf.h"
#include "stdlib/math/base/special/ln.h"
#include "stdlib/math/base/special/log1p.h"
#include "stdlib/constants/float64/ninf.h"
#include "stdlib/constants/float64/sqrt_two.h"

static const double INV_SQRT_TWO = 1.0 / STDLIB_CONSTANT_FLOAT64_SQRT2;  // 1/sqrt(2)

/**
* Evaluates the natural logarithm of the cumulative distribution function (CDF)
* for a half-normal distribution with scale parameter `sigma` at a value `x`.
*
* @param x      input value
* @param sigma  scale parameter
* @return evaluated log CDF
*
* @example
* double y = stdlib_base_dists_halfnormal_logcdf( 1.0, 1.0 );
* // returns ~-0.382
*/
double stdlib_base_dists_halfnormal_logcdf( const double x, const double sigma ) {
	double z;

	if (
		stdlib_base_is_nan( x ) ||
		stdlib_base_is_nan( sigma ) ||
		sigma <=0.0
	) {
		return 0.0 / 0.0; // NaN
	}
	if ( x < 0.0 ) {
		return STDLIB_CONSTANT_FLOAT64_NINF;
	}

	z = x / sigma;

	return stdlib_base_ln( stdlib_base_erf( z * INV_SQRT_TWO ) );
}
